\title{The Mega-Sphere: Inverse Limits, Characteristic Classes,\\ and Bernoulli Numbers}
\author{Aristotle}
\date{\today}

\begin{document}
\begin{abstract}
We develop the rigorous algebraic skeleton behind the \emph{mega-sphere} idea: a
single universal object that recovers every finite stage of an infinite tower at
once. First, we construct the \textbf{inverse limit} of a tower of additive
groups (and rings) as a concrete subobject of the product, establish its
projections and their coherence, and prove its full \textbf{universal property}
(existence and uniqueness of the mediating map). We evaluate two extreme towers:
the doubling tower $\Z \xleftarrow{\times 2} \Z \xleftarrow{\times 2} \cdots$
collapses to the trivial group, whereas the $2$-adic tower $\Z/2^{n+1}\Z$ has a
nontrivial inverse limit. Second, we record the cohomological fingerprint
$\Hcoh^{*}(\RP^{\infty};\Ftwo)\cong\Ftwo[w]$, the total Stiefel--Whitney class
$1+w$, its product behaviour, and the dual class $\overline{w}=\sum_{k\ge0}w^k$
inverting $1+w$ in $\Ftwo[[w]]$. Third, we prove the Bernoulli \textbf{recurrence}
$\sum_{k<n}\binom{n}{k}B_k=0$ for $n\ne1$, the vanishing of odd Bernoulli numbers
$B_{2n+3}=0$, and the Bernoulli-driven \textbf{Faulhaber} power-sum formulas for
$\sum k$, $\sum k^2$, $\sum k^3$, the last being Nicomachus's identity
$\sum k^3=(\sum k)^2$.
\end{abstract}

\maketitle

\section{Introduction}
Many central objects of mathematics arise as infinite towers indexed by a
dimension or level of precision,
\[ \cdots \to X_{n+1}\xrightarrow{\ \pi_n\ }X_n\to\cdots\to X_1\to X_0. \]
The \emph{mega-sphere} program asks whether a single object can encode an entire
such tower simultaneously, so that projecting onto any coordinate returns the
corresponding stage. The precise embodiment is the \textbf{inverse limit}, the
universal cone over the tower. We build this construction from first principles,
prove its universal property, and then illustrate the mega-sphere philosophy in
two further arenas: the mod-$2$ cohomology of the infinite real projective space,
and the Bernoulli numbers governing power sums across all exponents. We are
careful about scope: the literal slogan braids several genuine but distinct
pieces of mathematics, and we isolate exactly those that are true and provable.

\section{Inverse limits of towers}

\subsection{Definition}
Let $(X_n)_{n\in\N}$ be additive groups with connecting homomorphisms
$\pi_n:X_{n+1}\to X_n$.

\begin{definition}[Inverse limit]
The \emph{inverse limit} $\invlim X_n$ is the subgroup of $\prod_n X_n$ of
\emph{coherent sequences}:
\[ \invlim X_n=\Big\{x\in\textstyle\prod_n X_n : \pi_n(x(n+1))=x(n)\ \text{for all }n\Big\}. \]
It contains $0$ and is closed under addition and negation, hence is a subgroup;
when the $X_n$ are rings and the $\pi_n$ ring maps, coherent sequences form a
subring.
\end{definition}

\subsection{Projections and coherence}
\begin{definition}[Projections]
For each $n$, the projection $p_n:\invlim X_n\to X_n$ is the restriction of the
coordinate evaluation $x\mapsto x(n)$; it is a homomorphism.
\end{definition}

\begin{proposition}[Coherence]
For every $n$ and coherent $x$, $\ \pi_n(p_{n+1}(x))=p_n(x)$.
\end{proposition}
\begin{proof}
$p_{n+1}(x)=x(n+1)$ and $p_n(x)=x(n)$, and membership is exactly
$\pi_n(x(n+1))=x(n)$.
\end{proof}

\subsection{The universal property}
\begin{theorem}[Universal property]\label{thm:univ}
Let $Y$ be an additive group with homomorphisms $g_n:Y\to X_n$ satisfying
$\pi_n\circ g_{n+1}=g_n$ for all $n$. Then:
\begin{enumerate}
\item \emph{(Existence)} there is a homomorphism $u:Y\to\invlim X_n$ with
$p_n\circ u=g_n$, given by $u(y)=(g_0(y),g_1(y),\dots)$;
\item \emph{(Uniqueness)} any $u'$ with $p_n\circ u'=g_n$ for all $n$ equals $u$.
\end{enumerate}
\end{theorem}
\begin{proof}
For existence, $u(y):n\mapsto g_n(y)$ is coherent by $\pi_n\circ g_{n+1}=g_n$, so
$u(y)\in\invlim X_n$; $u$ is a homomorphism and $p_n(u(y))=g_n(y)$. For
uniqueness, elements of the limit are equal iff they agree in every coordinate,
and $p_n(u'(y))=g_n(y)=p_n(u(y))$ for all $n$.
\end{proof}

\subsection{Two towers, two fates}
\begin{example}[Constant tower]
If $X_n=G$ and $\pi_n=\mathrm{id}_G$, coherence forces sequences to be constant,
so $\invlim X_n$ is the diagonal copy of $G$.
\end{example}

\begin{theorem}[Collapse of the doubling tower]
Let $X_n=\Z$ and $\pi_n(x)=2x$. Then $\invlim X_n=0$.
\end{theorem}
\begin{proof}
Coherence gives $x(0)=2^m x(m)$ for all $m$, so $2^m\mid x(0)$ for all $m$; hence
$x(0)=0$, and likewise every $x(n)=0$.
\end{proof}

\begin{theorem}[Nontriviality of the $2$-adic tower]
Let $X_n=\Z/2^{n+1}\Z$ with $\pi_n$ the reduction map. Then $\invlim X_n$ is
nontrivial; it is the ring $\Z_2$ of $2$-adic integers.
\end{theorem}
\begin{proof}[Proof sketch]
The residues $1\bmod 2^{n+1}$ form a coherent nonzero sequence. More generally,
coherent sequences of residues modulo powers of $2$ are by definition the
elements of $\Z_2$, with the $p_n$ the standard truncations.
\end{proof}

The contrast is the moral: the same universal construction yields either the
trivial object or a genuinely new number system, depending only on the gluing.

\section{The cohomological fingerprint of $\RP^{\infty}$}
Let $\RP^{\infty}=\bigcup_n\RP^n$ be the infinite real projective space.

\begin{theorem}[Cohomology ring]
$\Hcoh^{*}(\RP^{\infty};\Ftwo)\cong\Ftwo[w]$, $\deg w=1$, the polynomial ring in
one generator; $w=w_1$ is the first Stiefel--Whitney class.
\end{theorem}

This is the rank-one case ($BO(1)=\RP^{\infty}$) of
$\Hcoh^{*}(BO;\Ftwo)=\Ftwo[w_1,w_2,\dots]$.

\begin{definition}[Total class and product formula]
The total Stiefel--Whitney class is $w(E)=1+w_1(E)+w_2(E)+\cdots$, and for direct
sums $w(E\oplus F)=w(E)\,w(F)$, the Whitney product formula.
\end{definition}

\begin{theorem}[Dual class in the completion]
In $\Ftwo[[w]]$ the total class $1+w$ is a unit with inverse
\[ \overline{w}=\sum_{k=0}^{\infty}w^k,\qquad (1+w)\,\overline{w}=1. \]
\end{theorem}
\begin{proof}
A power series over a field is a unit iff its constant term is; here it is $1$.
Explicitly $(1+w)\sum_{k\ge0}w^k=\sum_{k\ge0}w^k+\sum_{k\ge0}w^{k+1}=1$ by
telescoping.
\end{proof}

The completion is the "all dimensions at once" step: $\Ftwo[[w]]$ is the inverse
limit of the truncations $\Ftwo[w]/(w^{n+1})$, so the completed cohomology ring
is itself a mega-object in the sense of Theorem~\ref{thm:univ}.

\section{Bernoulli numbers as universal arithmetic invariants}

\subsection{Recurrence and small values}
\begin{theorem}[Bernoulli recurrence]
For every $n\ne1$, $\ \sum_{k=0}^{n-1}\binom{n}{k}B_k=0$. With $B_0=1$ this
determines every $B_n$.
\end{theorem}
\begin{proof}
Specialize the identity $\sum_{k=0}^{n}\binom{n}{k}B_k=B_n+[n{=}1]$ and isolate
the top term.
\end{proof}
The first values are $B_0=1,\ B_1=-\tfrac12,\ B_2=\tfrac16,\ B_3=0,\
B_4=-\tfrac1{30},\dots$; in particular $B_2=1/6$.

\subsection{Parity}
\begin{theorem}[Odd vanishing]
$B_{2n+3}=0$ for all $n\ge0$; equivalently $B_m=0$ for odd $m\ge3$.
\end{theorem}
\begin{proof}[Proof sketch]
The generating function $\frac{t}{e^t-1}+\frac{t}{2}$ is even, so all odd Taylor
coefficients vanish; translating back gives $B_m=0$ for odd $m\ge3$.
\end{proof}
This parity is why $\zeta(1-2k)=-B_{2k}/2k$ and the Hirzebruch $L$- and
$\hat A$-genera involve only even-index Bernoulli numbers.

\subsection{Faulhaber and Nicomachus}
For each $p$,
\[ \sum_{k=0}^{n-1}k^p=\frac1{p+1}\sum_{j=0}^{p}\binom{p+1}{j}B_j\,n^{p+1-j}. \]
\begin{theorem}[Faulhaber, $p=1,2,3$]
\[ \sum_{k=0}^{n-1}k=\frac{n(n-1)}2,\quad
\sum_{k=0}^{n-1}k^2=\frac{n(n-1)(2n-1)}6,\quad
\sum_{k=0}^{n-1}k^3=\Big(\frac{n(n-1)}2\Big)^2. \]
\end{theorem}
\begin{corollary}[Nicomachus]
$\ \sum_{k=0}^{n-1}k^3=\big(\sum_{k=0}^{n-1}k\big)^2$, holding precisely because
$B_3=0$.
\end{corollary}

\section{Algorithms}
\textbf{(A) Coherent-sequence test.} Check $\pi_n(x_{n+1})=x_n$ for $0\le n<N$;
$O(N)$ evaluations. \textbf{(B) Bernoulli by recurrence.} $B_0=1$, then
$B_{n-1}=-\tfrac1n\sum_{k=0}^{n-2}\binom nk B_k$; $O(N^2)$ rational operations.
\textbf{(C) Faulhaber coefficients.} Assemble
$\tfrac1{p+1}\binom{p+1}{j}B_j$ and evaluate in closed form.

\section{Applications and discussion}
The $2$-adic tower opens $p$-adic number theory; the cohomology ring and product
formula underlie obstruction theory; odd vanishing explains Bernoulli numbers in
$\zeta(1-2k)$ and in genera; Faulhaber gives exact power sums. The rigorous core
is the inverse-limit construction with its universal property and the two
concrete evaluations; the further strands exhibit the mega-sphere philosophy in
cohomology and arithmetic without overclaiming a single topological object whose
projections are the spheres $S^0,S^1,\dots$.

\section{Future directions}
\begin{enumerate}
\item Prove $\Ftwo[[w]]\cong\invlim\Ftwo[w]/(w^{n+1})$ via the universal property.
\item Prove surjectivity of all $2$-adic projections (Mittag-Leffler).
\item Extend to $BO(k)$ and $BO$ with the full Whitney product formula.
\item Link Bernoulli numbers to the $L$- and $\hat A$-genera and the
$J$-homomorphism.
\item Realize the tower genuinely in the category of spaces.
\end{enumerate}

