from typing import Callable, Sequence

def is_coherent(seq: Sequence[int], pi: Callable[[int, int], int]) -> bool:
    return all(pi(n, seq[n + 1]) == seq[n] for n in range(len(seq) - 1))

def two_adic_pi(n: int, x: int) -> int:
    return x % (2 ** (n + 1))

# doubling tower: only all-zero survives to all stages
print("all-zero coherent?", is_coherent([0, 0, 0, 0], lambda n, x: 2 * x))
# 2-adic tower: residues of a fixed integer are coherent and nonzero
for value in (1, 5, 13):
    res = [value % (2 ** (n + 1)) for n in range(6)]
    print(value, res, is_coherent(res, two_adic_pi))

from typing import List

def poly_mul_mod2(a: List[int], b: List[int], truncate: int) -> List[int]:
    out = [0] * truncate
    for i, ai in enumerate(a):
        if ai % 2:
            for j, bj in enumerate(b):
                if i + j < truncate and bj % 2:
                    out[i + j] ^= 1
    return out

N = 8
total = [1, 1]        # 1 + w
dual = [1] * N        # 1 + w + w^2 + ...
print(poly_mul_mod2(total, dual, N))   # -> [1, 0, 0, 0, 0, 0, 0, 0]

