function BERNOULLI(N):
    B[0] <- 1
    for m from 1 to N:
        s <- sum over k in [0, m-1] of C(m+1, k) * B[k]
        B[m] <- -s / C(m+1, m)
    return B[0..N]

function FAULHABER(p, n, B):
    total <- 0
    for j from 0 to p:
        total <- total + C(p+1, j) * B[j] * n^(p+1-j)
    return total / (p + 1)

